// Native datasource for HtmConversion — the zuraffa data layer's wrapper
// around the EXISTING dart:ffi bridge (spec 064 FR-004). The binding logic
// (options json -> handle -> htm_convert -> result json) lives in the shared
// platform package so the federated adapters can run the same conversion
// without depending on this package; this datasource only carries it through
// the generated contract. NOT generated by zfa — an implementation of the
// generated [HtmConversionDataSource] contract.
import 'package:html_to_markdown_ffi_platform/html_to_markdown_ffi_platform.dart'
    show NativeLibrary, Visitor, convertWithNativeLibrary;
import 'package:zuraffa/zuraffa.dart';

import '../../../domain/entities/htm_conversion/htm_conversion.dart';
import 'htm_conversion_datasource.dart';

/// Converts HTML to Markdown through the native bridge.
///
/// The request travels as an [HtmConversion] entity (`html` + `optionsJson`);
/// the bridge's result json lands back in `resultJson`. [convertNow] is the
/// synchronous in-process path (dart:ffi is synchronous); [get] adapts it to
/// the generated async contract.
class NativeHtmConversionDataSource
    with Loggable, FailureHandler
    implements HtmConversionDataSource {
  NativeHtmConversionDataSource({NativeLibrary? library})
      : _libraryOverride = library;

  final NativeLibrary? _libraryOverride;

  /// The preserved synchronous bridge call. [visitor] travels out of band
  /// (it is a callback, not JSON). Throws the preserved public exceptions
  /// (`InvalidInputException`, `ConversionErrorException`) via
  /// `checkLastError`.
  HtmConversion convertNow(HtmConversion request, {Visitor? visitor}) {
    final resultJson = convertWithNativeLibrary(
      request.html,
      optionsJson: request.optionsJson,
      visitor: visitor,
      library: _libraryOverride ?? NativeLibrary(),
    );
    return request.copyWith(resultJson: resultJson);
  }

  @override
  Future<HtmConversion> get(QueryParams<HtmConversion> params) async {
    final request = params.params?['request'];
    if (request is! HtmConversion) {
      throw ArgumentError.value(
        request,
        'params[request]',
        'Expected the HtmConversion request entity',
      );
    }
    final visitor = params.params?['visitor'];
    return convertNow(request, visitor: visitor is Visitor ? visitor : null);
  }

  @override
  Future<HtmConversion> update(
    UpdateParams<String, HtmConversionPatch> params,
  ) async {
    throw UnsupportedError(
        'HtmConversion is produced by conversion, not updated in place');
  }

  @override
  Future<HtmConversion> toggle(
    ToggleParams<String, Field<HtmConversion, dynamic>> params,
  ) async {
    throw UnsupportedError(
        'HtmConversion is produced by conversion, not toggled in place');
  }
}
